Here's a C++ function that converts markdown formatted text to HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::string line;
    std::istringstream stream(markdown);

    while (std::getline(stream, line)) {
        // Convert markdown line to HTML
        html += "<p>" + line + "</p>";
    }

    return html;
}

int main() {
    std::string markdown = "This is a first paragraph.\nThis is a second paragraph.\nThis is a third paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text. It uses a `std::istringstream` to read the markdown text line by line and converts each line to HTML by wrapping it in `<p>` tags. The resulting HTML string is returned.

Note that this function assumes that the markdown text is formatted in paragraphs, where each line is a paragraph and should be wrapped in `<p>` tags.

